// Photography map: Leaflet circles per place + full-screen carousel.
// Data: data/places.json (generated by scripts/build_photos.py)
(function () {
  const COLORS = { field: "#6FB3AB", nature: "#9DB8A6", travel: "#B9A3D0" };
  const $ = (id) => document.getElementById(id);
  document.body.appendChild($("pm-modal")); // escape any parent stacking context
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  const map = L.map("pm-map", { zoomControl: false, worldCopyJump: true, minZoom: 2 }).setView([15, -20], 2);
  L.control.zoom({ position: "topright" }).addTo(map);
  // Esri Light Gray Canvas: free, no API key; tinted to the brand palette in photo-map.css
  L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}", {
    attribution: "Tiles &copy; Esri &mdash; Esri, HERE, Garmin, &copy; OpenStreetMap contributors",
    maxZoom: 16,
  }).addTo(map);

  let places = [], current = null, idx = 0, lastFocus = null;

  fetch("data/places.json")
    .then((r) => r.json())
    .then((data) => {
      places = data.filter((p) => p.photos && p.photos.length);
      if (places.some((p) => p.sample)) $("pm-sample").hidden = false;
      draw();
    })
    .catch((e) => console.error("Could not load places.json", e));

  function draw() {
    const bounds = [];
    const list = $("pm-list");
    places.forEach((p, i) => {
      const color = COLORS[p.category] || COLORS.travel;
      const n = p.photos.length;
      const r = 7 + 3.2 * Math.sqrt(n);
      // soft halo + solid core
      L.circleMarker([p.lat, p.lng], { radius: r + 7, stroke: false, fillColor: color, fillOpacity: 0.22, interactive: false }).addTo(map);
      const m = L.circleMarker([p.lat, p.lng], {
        radius: r, color: "#fff", weight: 2.5, fillColor: color, fillOpacity: 0.92, className: "pm-marker",
      }).addTo(map);
      m.bindTooltip(
        `<img src="${esc(p.photos[0].thumb)}" alt=""><div class="t">${esc(p.title)}</div><div class="s">${esc(p.region)} · ${n} photo${n > 1 ? "s" : ""}</div>`,
        { className: "pm-tip", direction: "top", offset: [0, -r], opacity: 1 }
      );
      m.on("click", () => open(i));
      bounds.push([p.lat, p.lng]);

      const li = document.createElement("li");
      li.tabIndex = 0;
      li.innerHTML = `<img src="${esc(p.photos[0].thumb)}" alt="" loading="lazy">
        <div><div class="n">${esc(p.title)}</div>
        <div class="m"><span class="pm-dot ${esc(p.category)}"></span>${esc(p.region)}${p.date ? " · " + esc(String(p.date).slice(0, 4)) : ""}</div></div>`;
      li.addEventListener("click", () => { map.flyTo([p.lat, p.lng], Math.max(map.getZoom(), 6), { duration: 0.8 }); setTimeout(() => open(i), 650); });
      li.addEventListener("keydown", (e) => { if (e.key === "Enter") open(i); });
      list.appendChild(li);
    });
    if (bounds.length) {
      // leave room for the side panel only when the map is wide enough to spare it
      const wide = map.getSize().x > 1100;
      map.fitBounds(bounds, { paddingTopLeft: [wide ? 380 : 30, 40], paddingBottomRight: [40, 40], maxZoom: 6 });
      if (map.getZoom() > 4 && bounds.length > 1) map.fitBounds(bounds, { padding: [30, 30], maxZoom: 6 });
    }
  }

  // ---------- carousel ----------
  function open(i) {
    current = places[i];
    idx = 0;
    lastFocus = document.activeElement;
    $("pm-m-title").textContent = current.title;
    $("pm-m-region").textContent = [current.region, current.date && String(current.date).slice(0, 4)].filter(Boolean).join(" · ");
    $("pm-m-blurb").textContent = current.blurb || "";
    const thumbs = $("pm-thumbs");
    thumbs.innerHTML = "";
    current.photos.forEach((ph, j) => {
      const b = document.createElement("button");
      b.setAttribute("aria-label", `Photo ${j + 1}`);
      b.innerHTML = `<img src="${esc(ph.thumb)}" alt="" loading="lazy">`;
      b.onclick = () => show(j);
      thumbs.appendChild(b);
    });
    $("pm-modal").hidden = false;
    document.body.style.overflow = "hidden";
    show(0);
    $("pm-close").focus();
  }

  function show(j) {
    const ps = current.photos;
    idx = (j + ps.length) % ps.length;
    const ph = ps[idx], img = $("pm-img");
    img.style.opacity = 0;
    img.onload = () => (img.style.opacity = 1);
    img.src = ph.src;
    img.alt = ph.caption || `${current.title}, photo ${idx + 1}`;
    $("pm-cap").textContent = ph.caption || "";
    $("pm-count").textContent = `${idx + 1} / ${ps.length}`;
    [...$("pm-thumbs").children].forEach((b, k) => b.classList.toggle("on", k === idx));
    $("pm-thumbs").children[idx]?.scrollIntoView({ block: "nearest", inline: "center", behavior: "smooth" });
    // preload neighbours
    [1, -1].forEach((d) => { const n = ps[(idx + d + ps.length) % ps.length]; if (n) new Image().src = n.src; });
  }

  function close() {
    $("pm-modal").hidden = true;
    document.body.style.overflow = "";
    lastFocus?.focus?.();
  }

  $("pm-prev").onclick = () => show(idx - 1);
  $("pm-next").onclick = () => show(idx + 1);
  $("pm-close").onclick = close;
  $("pm-modal").addEventListener("click", (e) => { if (e.target.id === "pm-modal") close(); });
  document.addEventListener("keydown", (e) => {
    if ($("pm-modal").hidden) return;
    if (e.key === "Escape") close();
    if (e.key === "ArrowRight") show(idx + 1);
    if (e.key === "ArrowLeft") show(idx - 1);
  });
  // swipe on touch devices
  let x0 = null;
  $("pm-modal").addEventListener("touchstart", (e) => (x0 = e.touches[0].clientX), { passive: true });
  $("pm-modal").addEventListener("touchend", (e) => {
    if (x0 === null) return;
    const dx = e.changedTouches[0].clientX - x0;
    if (Math.abs(dx) > 50) show(idx + (dx < 0 ? 1 : -1));
    x0 = null;
  });
})();
